      "content": "{\n  \"schemaVersion\": 1,\n  \"id\": \"sidechat\",\n  \"source\": \"official\",\n  \"displayName\": \"Sidechat\",\n  \"description\": \"A side-chat panel on the dsh Web workbench for quick questions in a separate, memory-only session. Two packages: Workbench UI first, then Sidechat itself.\",\n  \"descriptionZh\": \"dsh Web 工作台侧边的快速问答面板，使用独立的内存会话。两包安装：先 Workbench UI，再 Sidechat。\",\n  \"author\": { \"name\": \"Ephemeral AI Lab\", \"url\": \"https://github.com/Ephemeral-AI-Lab\" },\n  \"links\": {\n    \"repo\": \"https://github.com/Ephemeral-AI-Lab/dsh-plugins/tree/main/plugins/sidechat\",\n    \"docs\": \"https://github.com/Ephemeral-AI-Lab/dsh-plugins/blob/main/plugins/sidechat/README.md\"\n  },\n  \"license\": \"MIT\",\n  \"category\": \"ui\",\n  \"status\": \"beta\",\n  \"surfaces\": { \"server\": {}, \"web\": { \"clientModule\": true } },\n  \"provides\": {},\n  \"install\": {\n    \"rows\": [\n      {\n        \"id\": \"workbench-ui\",\n        \"name\": \"dsh-workbench-ui\",\n        \"github\": { \"repo\": \"Ephemeral-AI-Lab/dsh-plugins\", \"ref\": \"main\", \"subdir\": \"plugins/work-bench-ui\" }\n      },\n      {\n        \"id\": \"sidechat\",\n        \"name\": \"dsh-sidechat\",\n        \"github\": { \"repo\": \"Ephemeral-AI-Lab/dsh-plugins\", \"ref\": \"main\", \"subdir\": \"plugins/sidechat\" }\n      }\n    ]\n  },\n  \"capabilities\": [\"session-write\"],\n  \"verified\": {\n    \"at\": \"2026-09-04\",\n    \"packages\": [\n      { \"name\": \"dsh-workbench-ui\", \"version\": \"0.1.0\" },\n      { \"name\": \"dsh-sidechat\", \"version\": \"0.1.0\" }\n    ]\n  }\n}\n"
